**Gates before launch.** I run five gates in order and stop if any one fails. First, I confirm that spe/predictions/r04.yaml and spe/plans/r04.md are in the `SPE r04 predict` commit and have not changed since. Second, I check that spe/evals/tasks/answers.json holds 50 tickets and that their ids match args.tickets. The project notes say the eval set has 40 tickets. If the file holds 40, I stop and ask you, because a different ticket count changes the approved plan. Third, I run the grader selftest. The oracle answers must score 50 of 50, and an empty file and a file of wrong labels must both score 0. Fourth, I regrade the r03 outputs with this round's grade.py as a control. If the r03 numbers move, the grader changed, and I log that before any r04 number exists. Fifth, I dry run the script with `args.only = ['B:T001','C2:T001','C2:T027']`. I check that every trial returns valid output with a transcript path, that the scan finds no hits, that the grader returns every id, and that the judge scores every reply. Then I commit the script as `SPE r04 evaluate (harness)` and launch it. A Workflow agent cannot carry the triage tools itself. So I assumed the triage agent runs through a command given in `args.runner` that prints one JSON object per run.

```js
// spe/evals/harness/r04-workflow.js
export const meta = {
  name: 'spe-triage-eval',
  description: 'SPE evaluate step for the triage agent. Runs each config on each ticket, voids trials that peeked, grades labels with grade.py, judges reply tone blind with Opus, and keeps spend under the cap.',
  phases: ['Trials', 'Scan', 'Grade', 'Top-up', 'Judge', 'Synthesis'],
}

// ---- Round and arguments ----
const ROUND = 4
const RR = `r${String(ROUND).padStart(2, '0')}`

const CONFIGS = args.configs ?? ['B', 'C2']            // B = 12-line prompt, 6 tools. C2 = 12-line prompt, 3 tools plus check_status.
const TICKETS = args.tickets ?? []                       // ticket ids, passed in. The script has no filesystem access.
const EXPECTED_TICKETS = args.expectedTickets ?? 50
const TRIALS = args.trials ?? 5
const TOPUP_PER_CELL = args.topupPerCell ?? 3
const SPEND_CAP_USD = args.spendCapUsd ?? 40             // covers triage API spend (runner-reported) and judge calls (estimated)
const EST = args.estUsd ?? { trial: 0.04, judgeReply: 0.02 } // unmeasured estimates. Runner-reported cost replaces the trial estimate.
const MAX_PAID_AGENTS = args.maxPaidAgents ?? 300        // trial-cell agents plus judge agents
const RUNNER = args.runner                               // e.g. 'python3 -m triage.run'
const TICKET_DIR = args.ticketDir ?? 'spe/evals/tasks/tickets'
const ONLY = args.only ?? null                           // dry run, e.g. ['B:T001','C2:T001']
const CONCURRENCY = args.concurrency ?? 10
const JUDGE_BATCH = args.judgeBatch ?? 10
const AGENT_MODEL = args.agentModel ?? 'opus'
const JUDGE_MODEL = 'opus'
const SEED = args.seed ?? 20261021

const HIDDEN = 'spe/(evals|predictions|plans|spec)|prediction-log|failures\\.md|answers\\.json|grade\\.py|judge\\.md'
const HIDDEN_RE = new RegExp(HIDDEN)

if (!RUNNER) throw new Error('args.runner is required.')
if (!ONLY && TICKETS.length !== EXPECTED_TICKETS) {
  throw new Error(`args.tickets has ${TICKETS.length} ids. The approved plan says ${EXPECTED_TICKETS}. Halt and ask the user.`)
}

// ---- Budget ----
let spent = 0
let paidAgents = 0
let supportAgents = 0
const skips = []
const round2 = x => Math.round(x * 100) / 100
const canSpend = usd => spent + usd <= SPEND_CAP_USD && paidAgents + 1 <= MAX_PAID_AGENTS
function skip(what, detail) {
  skips.push({ what, ...detail, spent_usd: round2(spent) })
  log(`SKIP ${what}: ${JSON.stringify(detail)} (spent $${round2(spent)} of $${SPEND_CAP_USD})`)
}

// ---- Helpers ----
const chunk = (xs, n) => { const out = []; for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n)); return out }
async function inChunks(thunks, size) { const out = []; for (const g of chunk(thunks, size)) out.push(...await parallel(g)); return out }
const mean = xs => { const v = xs.filter(x => typeof x === 'number'); return v.length ? round2(v.reduce((a, b) => a + b, 0) / v.length) : null }
const rate = (xs, f) => xs.length ? round2(xs.filter(f).length / xs.length) : null
function shuffle(xs) {
  let s = SEED
  const rnd = () => { s = (s * 1664525 + 1013904223) % 4294967296; return s / 4294967296 }
  const a = [...xs]
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]] }
  return a
}

// ---- Schemas ----
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['commands', 'trials'],
  properties: {
    commands: { type: 'array', items: { type: 'string' } },
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['status'],
        properties: {
          status: { type: 'string', enum: ['completed', 'rate_limited', 'harness_error'] },
          error: { type: 'string' },
          label: { type: 'object', properties: { category: { type: 'string' }, priority: { type: 'string' } } },
          reply: { type: 'string' },
          runtime_ms: { type: 'number' },
          tool_calls: { type: 'number' },
          tool_errors: { type: 'number' },
          input_tokens: { type: 'number' },
          output_tokens: { type: 'number' },
          cost_usd: { type: 'number' },
          transcript_path: { type: 'string' },
        },
      },
    },
  },
}
const SCAN_SCHEMA = {
  type: 'object',
  required: ['checked', 'hits'],
  properties: {
    checked: { type: 'number' },
    hits: { type: 'array', items: { type: 'object', required: ['path'], properties: { path: { type: 'string' }, line: { type: 'string' } } } },
  },
}
const GRADE_SCHEMA = {
  type: 'object',
  required: ['crashed', 'results'],
  properties: {
    crashed: { type: 'boolean' },
    error: { type: 'string' },
    results: {
      type: 'array',
      items: { type: 'object', required: ['id', 'category_ok', 'priority_ok'], properties: { id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } } },
    },
  },
}
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: { type: 'object', required: ['rid', 'tone_score', 'tone_pass'], properties: { rid: { type: 'string' }, tone_score: { type: 'number' }, tone_pass: { type: 'boolean' }, reason: { type: 'string' } } },
    },
  },
}
const FAILURE_SCHEMA = {
  type: 'object',
  required: ['failure_types'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix'],
        properties: {
          id: { type: 'string' }, name: { type: 'string' }, kind: { type: 'string' }, what: { type: 'string' },
          how_to_spot: { type: 'string' }, seen_in: { type: 'array', items: { type: 'string' } }, fix: { type: 'string' },
        },
      },
    },
    possible_grader_or_key_errors: { type: 'array', items: { type: 'string' } },
  },
}
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } } },
}

// ---- Cells ----
function cellsFor(ids) {
  const all = []
  for (const cfg of CONFIGS) for (const tid of ids) all.push({ cfg, tid, key: `${cfg}:${tid}` })
  return ONLY ? all.filter(c => ONLY.includes(c.key)) : all
}

function trialPrompt(cell, n) {
  const cmd = `${RUNNER} --config ${cell.cfg} --ticket ${cell.tid} --json`
  return [
    'You run one cell of an evaluation harness. Your only job is to run a command and copy its output.',
    `Run this exact command ${n} times. Start a fresh process each time. Do not reuse output between runs.`,
    `  ${cmd}`,
    'Each run prints one JSON object with label.category, label.priority, reply, runtime_ms, tool_calls, tool_errors, input_tokens, output_tokens, cost_usd and transcript_path.',
    'Copy each object into one trials[] entry with status "completed". Copy the values exactly. Do not fix, normalize, or judge them.',
    'If a run fails on a rate limit, record status "rate_limited". If it fails for any other reason, record status "harness_error" and put the message in error. Do not retry.',
    'Rules: Do not open, read, list, or search any file or directory. Run no command other than the one above. List every command you ran, verbatim, in commands[].',
  ].join('\n')
}

async function runCell(cell, want, tag, firstK) {
  const phaseName = tag === 'trial' ? 'Trials' : 'Top-up'
  let n = want
  while (n > 0 && !canSpend(n * EST.trial)) n--
  if (n < want) skip(`${tag} ${cell.key}`, { trials_skipped: want - n })
  if (n === 0) return []
  const reserved = n * EST.trial
  spent += reserved
  paidAgents += 1
  const mk = (k, t) => ({ id: `${cell.key}:${k}`, cfg: cell.cfg, tid: cell.tid, k, tag, void: false, ...t })
  let res
  try {
    res = await agent(trialPrompt(cell, n), { label: `${tag} ${cell.key} x${n}`, phase: phaseName, schema: TRIAL_SCHEMA, model: AGENT_MODEL })
  } catch (e) {
    // Spend is unknown, so the reservation stays.
    return Array.from({ length: n }, (_, i) => mk(firstK + i, { status: 'harness_error', error: String(e) }))
  }
  const trials = res.trials.slice(0, n)
  while (trials.length < n) trials.push({ status: 'harness_error', error: 'runner agent returned fewer trials than asked' })
  const costs = trials.map(t => t.cost_usd)
  if (costs.every(c => typeof c === 'number')) spent += costs.reduce((a, b) => a + b, 0) - reserved
  const badCmd = res.commands.find(c => !c.trim().startsWith(RUNNER) || HIDDEN_RE.test(c))
  return trials.map((t, i) => {
    const r = mk(firstK + i, t)
    if (badCmd && r.status === 'completed') { r.void = true; r.void_reason = `runner agent ran a disallowed command: ${badCmd}` }
    return r
  })
}

// ---- Scan for peeks ----
async function scan(recs, phaseName) {
  const todo = recs.filter(r => r.status === 'completed' && !r.void)
  for (const r of todo) if (!r.transcript_path) { r.void = true; r.void_reason = 'no transcript to scan' }
  const paths = [...new Set(todo.filter(r => !r.void).map(r => r.transcript_path))]
  const hit = new Set()
  for (const batch of chunk(paths, 100)) {
    supportAgents += 1
    const out = await agent([
      'You scan evaluation transcripts for reads of hidden files. Report what grep finds. Do not interpret.',
      `For each path below, run: grep -nE '${HIDDEN}' <path>`,
      'Report every matching file and its first matching line in hits[]. Set checked to the number of files you scanned.',
      'Paths:',
      ...batch,
    ].join('\n'), { label: `scan ${batch.length} transcripts`, phase: phaseName, schema: SCAN_SCHEMA, model: AGENT_MODEL })
    if (out.checked !== batch.length) throw new Error(`Scanner checked ${out.checked} of ${batch.length} transcripts. Halt and report.`)
    for (const h of out.hits) hit.add(h.path)
  }
  for (const r of todo) if (!r.void && hit.has(r.transcript_path)) { r.void = true; r.void_reason = 'transcript references a hidden path' }
  const voided = todo.filter(r => r.void).length
  if (voided) log(`${phaseName}: voided ${voided} trials`)
}

// ---- Code grader ----
async function grade(recs, phaseName) {
  const todo = recs.filter(r => r.status === 'completed' && !r.void)
  for (const cfg of CONFIGS) {
    for (const batch of chunk(todo.filter(r => r.cfg === cfg), 150)) {
      supportAgents += 1
      const lines = batch.map(r => JSON.stringify({ id: r.id, ticket_id: r.tid, label: r.label ?? null }))
      const out = await agent([
        'You are the code grader for an evaluation. Do not grade by judgment. Run the grader script and copy its result.',
        '1. Write the JSON lines below to a new temp file under $TMPDIR. Do not write inside the repository.',
        '2. Run: python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --input <that file> --json',
        '3. For every input id, copy category_ok and priority_ok from the script output into results[].',
        'Set crashed to true if the script errored or printed no result, and put the error text in error.',
        'Do not edit grade.py or answers.json.',
        'JSON lines:',
        ...lines,
      ].join('\n'), { label: `grade ${cfg} (${batch.length})`, phase: phaseName, schema: GRADE_SCHEMA, model: AGENT_MODEL })
      const byId = new Map(out.results.map(x => [x.id, x]))
      const missing = batch.filter(r => !byId.has(r.id)).length
      if (out.crashed || missing) throw new Error(`Grader problem on ${cfg}: crashed=${out.crashed}, ${missing} of ${batch.length} ids missing. ${out.error ?? ''} Halt and report.`)
      for (const r of batch) {
        const g = byId.get(r.id)
        r.category_ok = g.category_ok
        r.priority_ok = g.priority_ok
        r.both_ok = g.category_ok && g.priority_ok
      }
    }
  }
}

// ---- Blind tone judge ----
async function judge(recs) {
  const todo = shuffle(recs.filter(r => r.status === 'completed' && !r.void && r.reply))
  const byRid = new Map(todo.map((r, i) => [`R${String(i + 1).padStart(4, '0')}`, r]))
  const batches = chunk([...byRid.entries()], JUDGE_BATCH)
  await inChunks(batches.map(b => async () => {
    const usd = b.length * EST.judgeReply
    if (!canSpend(usd)) { skip('judge batch', { replies_skipped: b.length }); return }
    spent += usd
    paidAgents += 1
    const items = b.map(([rid, r]) => JSON.stringify({ rid, ticket_id: r.tid, reply: r.reply }))
    const out = await agent([
      'You judge the tone of first replies to support tickets.',
      'Read the rubric at spe/evals/graders/judge.md and apply it exactly.',
      `Read each ticket at ${TICKET_DIR}/<ticket_id>.json so you know what the customer wrote.`,
      'Judge tone only. Do not judge the category or priority.',
      'Return one entry per rid with tone_score, tone_pass and a one-sentence reason.',
      'Replies:',
      ...items,
    ].join('\n'), { label: `judge ${b.length} replies`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL })
    for (const s of out.scores) {
      const r = byRid.get(s.rid)
      if (r) { r.tone_score = s.tone_score; r.tone_pass = s.tone_pass; r.tone_reason = s.reason }
    }
  }), CONCURRENCY)
}

// ---- Metrics ----
function summarize(recs) {
  const out = {}
  for (const cfg of CONFIGS) {
    const mine = recs.filter(r => r.cfg === cfg)
    const done = mine.filter(r => r.status === 'completed' && !r.void)
    const graded = done.filter(r => typeof r.both_ok === 'boolean')
    const judged = done.filter(r => typeof r.tone_pass === 'boolean')
    out[cfg] = {
      completed: done.length,
      voided: mine.filter(r => r.void).length,
      harness_errors: mine.filter(r => r.status === 'harness_error').length,
      rate_limited: mine.filter(r => r.status === 'rate_limited').length,
      category_acc: rate(graded, r => r.category_ok),
      priority_acc: rate(graded, r => r.priority_ok),
      both_acc: rate(graded, r => r.both_ok),
      tone_pass_rate: rate(judged, r => r.tone_pass),
      tone_mean: mean(judged.map(r => r.tone_score)),
      judged: judged.length,
      runtime_ms_mean: mean(done.map(r => r.runtime_ms)),
      tool_calls_mean: mean(done.map(r => r.tool_calls)),
      tool_errors_mean: mean(done.map(r => r.tool_errors)),
      tokens_mean: mean(done.map(r => (r.input_tokens ?? 0) + (r.output_tokens ?? 0))),
      cost_usd_total: round2(done.reduce((a, r) => a + (r.cost_usd ?? 0), 0)),
    }
  }
  return out
}

// ---- Run ----
const cells = cellsFor(TICKETS.length ? TICKETS : (ONLY ?? []).map(k => k.split(':')[1]))
log(`${RR}: ${cells.length} cells x ${TRIALS} trials. Spend cap $${SPEND_CAP_USD}. Paid agent cap ${MAX_PAID_AGENTS}.`)
log('Judge note: no judge from a different model family is available. The tone judge is Opus.')

phase('Trials')
const base = (await inChunks(cells.map(c => () => runCell(c, TRIALS, 'trial', 1)), CONCURRENCY)).flat()

phase('Scan')
await scan(base, 'Scan')

phase('Grade')
await grade(base, 'Grade')

phase('Top-up')
const split = cells.filter(c => {
  const g = base.filter(r => r.cfg === c.cfg && r.tid === c.tid && typeof r.both_ok === 'boolean')
  return g.some(r => r.both_ok) && g.some(r => !r.both_ok)
})
log(`${split.length} split cells get up to ${TOPUP_PER_CELL} extra trials each.`)
const extra = (await inChunks(split.map(c => () => runCell(c, TOPUP_PER_CELL, 'topup', TRIALS + 1)), CONCURRENCY)).flat()
if (extra.length) { await scan(extra, 'Top-up'); await grade(extra, 'Top-up') }
const all = [...base, ...extra]

phase('Judge')
await judge(all)

phase('Synthesis')
// Headline numbers use the planned trials only. Top-up trials lean toward split cells and would bias accuracy.
const headline = summarize(base)
const withTopup = summarize(all)

const misses = all.filter(r => r.both_ok === false).slice(0, 200)
  .map(r => ({ id: r.id, cfg: r.cfg, ticket_id: r.tid, label: r.label, category_ok: r.category_ok, priority_ok: r.priority_ok }))
const toneFails = all.filter(r => r.tone_pass === false).slice(0, 100)
  .map(r => ({ id: r.id, cfg: r.cfg, ticket_id: r.tid, reason: r.tone_reason }))

supportAgents += 1
const failureAnalysis = await agent([
  'You analyze failures from a finished evaluation of a support-ticket triage agent.',
  'You may read spe/evals/tasks/answers.json, spe/failures.md and the ticket files. The trials are finished.',
  'Group the misses below into failure types. Continue the F-numbering from spe/failures.md. Reuse an existing F-number when a miss matches a known type.',
  'For each type give id, name, kind, what, how_to_spot, seen_in (trial ids) and fix.',
  'If a miss looks like a wrong reference label or a grader bug, list it in possible_grader_or_key_errors and also as its own failure type.',
  `Headline metrics: ${JSON.stringify(headline)}`,
  `Label misses: ${JSON.stringify(misses)}`,
  `Tone fails: ${JSON.stringify(toneFails)}`,
].join('\n'), { label: 'failure analysis', phase: 'Synthesis', schema: FAILURE_SCHEMA, model: AGENT_MODEL })

supportAgents += 1
const critic = await agent([
  'You check whether an evaluation run is complete enough to report. Do not rerun anything.',
  `Planned: ${cells.length} cells, ${TRIALS} trials each, configs ${CONFIGS.join(', ')}.`,
  `Headline: ${JSON.stringify(headline)}`,
  `With top-up: ${JSON.stringify(withTopup)}`,
  `Skips: ${JSON.stringify(skips)}`,
  `Voided trials: ${JSON.stringify(all.filter(r => r.void).map(r => ({ id: r.id, reason: r.void_reason })))}`,
  `Spend: $${round2(spent)} of $${SPEND_CAP_USD}. Paid agents: ${paidAgents} of ${MAX_PAID_AGENTS}.`,
  `Failure analysis: ${JSON.stringify(failureAnalysis)}`,
  'List every gap. Check for cells with no completed trials, replies never judged, skips that change a headline number, harness errors counted as model failures, and failure types with no fix.',
].join('\n'), { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: AGENT_MODEL })

return {
  round: ROUND,
  dry_run: Boolean(ONLY),
  spend_usd: round2(spent),
  spend_cap_usd: SPEND_CAP_USD,
  paid_agents: paidAgents,
  support_agents: supportAgents,
  skips,
  headline,
  with_topup: withTopup,
  split_cells: split.map(c => c.key),
  failure_analysis: failureAnalysis,
  critic,
  records: all.map(({ reply, ...r }) => r),
}
```
